"""THE ARM FAMILIES' GENERATED FILES, written from a family's rows file (`{"key": [...], "arms": [[...], ...]}`): its selection header, its Python
table and its declarations, and the merge of declaration files into the one file the SASS gate reads. Run by `bazel/arms.bzl`'s rules; the
rows are a literal's (`arm_rows`) or `arms_gen`'s (docs/internals/decode/arms_gen.md). Docs: docs/build-graph.md#arms.
"""
from __future__ import annotations

import argparse
import json
from pathlib import Path


def rows_of(path: Path) -> tuple[list[str], list[list[int]]]:
    data = json.loads(path.read_text())
    key, arms = data["key"], data["arms"]
    for row in arms:
        if len(row) != len(key):
            raise SystemExit(f"{path}: row {row} is not the key {key} as {len(key)} integers")
    if len({tuple(r) for r in arms}) != len(arms):
        raise SystemExit(f"{path}: a row is declared twice; a duplicate would give one kernel two indices")
    if arms != sorted(arms):
        raise SystemExit(f"{path}: the rows are not in canonical order: an arm's index is named by the selection header and the units, "
                         f"so it is a property of the declaration. Sorted: {sorted(arms)}")
    return key, arms


def selection(family: str, key: list[str], rows: list[list[int]], picked: list[int], includer: str, flag: str) -> str:
    up = family.upper()
    out = ["// GENERATED by bazel/arms.bzl -- do not edit.\n",
           f"// the {up} ARM SELECTION for this build. NEVER CHECKED IN;\n",
           f"// written by the graph (from {flag}).\n",
           f"// Included only by {includer}.\n",
           f"#define FSLA_{up}_BUILT 1\n"]
    for i in picked:
        out.append(f"#define FSLA_{up}_BUILD_{i} 1\n")
    out.append(f"\n// THE ARM SET, for the host's dispatch: one F(i, {', '.join(key)})\n")
    out.append("// per BUILT arm, in index order. See docs/build-graph.md#arms\n")
    out.append(f'#define FSLA_{up}_ARM_FAMILY "{family}"\n')
    out.append(f'#define FSLA_{up}_ARM_KEY "({", ".join(key)})"\n')
    out.append(f"#define FSLA_{up}_ARM_FIELDS {', '.join(json.dumps(k) for k in key)}\n")
    out.append(f"#define FSLA_{up}_ARM_COUNT {len(picked)}\n")
    out.append(f"#define FSLA_{up}_ARM_DECLARED {len(rows)}\n")
    if picked:
        body = " \\\n".join(f"  F({i}, {', '.join(str(v) for v in rows[i])})" for i in picked)
        out.append(f"#define FSLA_{up}_ARM_SET_X(F) \\\n{body}\n")
    else:
        out.append(f"//: NO ARM IS BUILT: the X-macro expands to nothing, `FSLA_{up}_ARM_COUNT` is 0,\n")
        out.append("//: and the host's dispatch refuses every call by naming the empty set. That is the\n")
        out.append("//: honest state of a family with no kernels, not a hole.\n")
        out.append(f"#define FSLA_{up}_ARM_SET_X(F)\n")
    return "".join(out)


def table(family: str, key: list[str], rows: list[list[int]]) -> str:
    keys = ", ".join(json.dumps(k) for k in key) + ("," if len(key) == 1 else "")
    body = "".join(f"\n    ({', '.join(str(v) for v in row)}{',' if len(row) == 1 else ''})," for row in rows) + ("\n" if rows else "")
    return ('"""GENERATED by bazel/arms.bzl -- do not edit.\n\n'
            f"The {family} family's declared arms: `KEY` names a row's fields, `ARMS` is the arm table, arm `i` everywhere.\n"
            '"""\n\n'
            f"KEY = ({keys})\n"
            f"ARMS = ({body})\n")


def kernel_pattern(pattern: str, key: list[str], row: list[int], arch: str) -> str:
    """An arm's exact kernel pattern: `pattern` (escaped and anchored by `bazel/cuda.bzl`'s `kernel_pattern`, the one place a name is) with each `@<field>@` a
    field of the key and `@cc@` the architecture's compute capability as `__CUDA_ARCH__` reads it (`90a` is 900)."""
    values = {field: str(value) for field, value in zip(key, row)}
    values["cc"] = str(int(arch.removesuffix("a")) * 10)
    parts = pattern.split("@")
    for i in range(1, len(parts), 2):
        if parts[i] not in values:
            raise SystemExit(f"{pattern}: `@{parts[i]}@` is no field of the key {key} (nor `cc`)")
        parts[i] = values[parts[i]]
    return "".join(parts)


def declarations(family: str, key: list[str], rows: list[list[int]], picked: list[int], kernel: str, declared: list[dict], archs: list[str]) -> dict:
    found, arms = [], []
    for arch in archs:
        on = "sm_" + arch
        for i in picked:
            pattern = kernel_pattern(kernel, key, rows[i], arch)
            arms.append({"arch": on, "family": family, "arm": i, "kernel": pattern})
            for d in declared:
                if d["arch"] in (None, on) and all(rows[i][key.index(f)] in wanted for f, wanted in d["where"].items()):
                    found.append({"arch": on, "kernel": pattern, "rule": d["rule"], "allow": d["allow"], "reason": d["reason"]})
    return {"declarations": found, "arms": arms}


def merge(base: dict, files: list[Path]) -> dict:
    """The gate's declarations file: `base` (`{"architectures": {arch: {"declarations", "arms"}}}`) with each file's findings added to their architectures."""
    spec = base["architectures"]
    for path in files:
        data = json.loads(path.read_text())
        for d in data["declarations"]:
            if d["arch"] in spec:
                spec[d["arch"]]["declarations"].append({k: d[k] for k in ("kernel", "rule", "allow", "reason")})
        for arm in data["arms"]:
            if arm["arch"] in spec:
                spec[arm["arch"]]["arms"].append({"family": arm["family"], "arm": arm["arm"], "kernel": arm["kernel"]})
    return base


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("what", choices=("selection", "table", "declarations", "merge"))
    ap.add_argument("--rows", type=Path)
    ap.add_argument("--family", default="")
    ap.add_argument("--includer", default="")
    ap.add_argument("--selected", default="all", help="the arms the header names: `all` (every row: the arms the build's contract reaches) or comma-separated indices (empty for none: a probe's)")
    ap.add_argument("--kernel", default="")
    ap.add_argument("--declared", action="append", default=[], help="a declaration, JSON")
    ap.add_argument("--archs", default="")
    ap.add_argument("--base", type=Path)
    ap.add_argument("--file", action="append", default=[], type=Path)
    ap.add_argument("--out", type=Path, required=True)
    a = ap.parse_args()
    if a.what == "merge":
        a.out.write_text(json.dumps(merge(json.loads(a.base.read_text()), a.file), indent=2) + "\n")
        return 0
    key, rows = rows_of(a.rows)
    knob = "--//:contract"
    picked = list(range(len(rows))) if a.selected == "all" else sorted(int(i) for i in a.selected.split(",") if i)
    for i in picked:
        if i >= len(rows):
            raise SystemExit(f"{a.family}: no such arm {i}; the list has {len(rows)} rows (0..{len(rows) - 1})")
    if a.what == "selection":
        a.out.write_text(selection(a.family, key, rows, picked, a.includer, knob))
    elif a.what == "table":
        a.out.write_text(table(a.family, key, rows))
    else:
        out = declarations(a.family, key, rows, picked, a.kernel, [json.loads(d) for d in a.declared], [x for x in a.archs.split(",") if x])
        a.out.write_text(json.dumps(out, indent=1) + "\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
